import{_ as n,a0 as p,w as i,s,ao as u,I as l,x as e,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"文档并不是开源项目开发的附属品 | LCTT x X-CMD","titleTemplate":false,"description":"文档并不是开源项目开发的附属品 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"文档并不是开源项目开发的附属品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"文档并不是开源项目开发的附属品 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220422 Documentation Isn’t Just Another Aspect of Open Source Development","title":"文档并不是开源项目开发的附属品","tag":"202205","desc":""},"relativePath":"202205/20220422 Documentation Isn’t Just Another Aspect of Open Source Development.md","filePath":"[post].md"}'),d={name:"202205/20220422 Documentation Isn’t Just Another Aspect of Open Source Development.md"};function m(h,t,f,b,x,T){const r=p("Link");return i(),s("div",null,[t[15]||(t[15]=u('<h1 id="文档并不是开源项目开发的附属品" tabindex="-1">文档并不是开源项目开发的附属品 <a class="header-anchor" href="#文档并不是开源项目开发的附属品" aria-label="Permalink to “文档并不是开源项目开发的附属品”">​</a></h1><p>有些项目长期保持活跃，有些项目却过早消亡 —— 这两者的区别往往在于它们的文档。严谨、聪明的文档可以给你的项目带来它所需要的动力。你应该把文档工作视为一项主要工作，把它与开发相提并论，下面我将说明这么做的理由和正确的做法。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202205/05/090003l7xrtrwszw6u4wqu.jpg" alt=""></p><p>经常会有开发者简单地认为他们的代码的“<ruby>自我描述<rt>self-documented</rt></ruby>”已经足够了，继而认为额外的文档是没有必要的。这种过度的自信会让项目付出很大的代价。匮乏或差劲的文档会扼杀你的项目。没有适当的文档，用户将无法理解项目的目标以及正确的工作流程。这可能会导致人们对采用你的开源产品产生一些疑虑。</p><h3 id="撰写文档-从项目第一天就开始" tabindex="-1">撰写文档，从项目第一天就开始 <a class="header-anchor" href="#撰写文档-从项目第一天就开始" aria-label="Permalink to “撰写文档，从项目第一天就开始”">​</a></h3><p>文档不应该是次要的工作，它应该是与代码开发和管理同等的主要任务。随着内容以 Community Threads、Stack Overflow 和 Quora 问答等形式的广泛传播，文档承担了“<ruby>信息源<rt>source of truth</rt></ruby>”的角色。它应该满足那些想参考一手资料的贡献者的需要，并给工程师提供必要的参考支持。它还应该与利益相关者沟通基本计划。一个好的文档可以确保产品的持续改进和发展。</p><p>当发布一个软件产品时，我们不仅要发布代码，还要发布好的文档。这给我们带来了一个最重要的概念，大多数良好维护了文档的开源项目都遵循这个概念 —— “<ruby>文档即代码<rt>Documentation as code</rt></ruby>”。</p><h3 id="文档及代码" tabindex="-1">文档及代码 <a class="header-anchor" href="#文档及代码" aria-label="Permalink to “文档及代码”">​</a></h3><p>今天，文档不再被存储为微软 Word 或 PDF 文件。新的需求是版本控制文档，其中所有的文档都是通过版本控制系统添加的，并持续发布。这个概念因 Read the Docs（LCTT 译注：一个文档创建、托管和浏览的平台）而流行，现在已经成为大多数文档团队的内容策略的重要组成部分。</p><p>像 Bugzilla 和 GitHub <ruby>议题<rt>Issue</rt></ruby>这样的工具可以用来跟踪待处理的文档工作，并从维护者和用户那里获得反馈以验证文档的发布。外部审查可以用来验证文档作品，并持续发布文档。这就保证了除代码外，文档也能不断改进并快速发布。</p><p>请记住，如果不遵循规范化的实践，每个文档都会不同。这可能会导致一些混乱，使人们难以获取正确的信息。</p><p>哪些东西会被归类为混乱呢？当大多数文件都不遵循规范实践时，不一致就会产生，从而导致更大的混乱！那么，如何整理混乱的开源文档呢？</p><h3 id="整理混乱的开源文档" tabindex="-1">整理混乱的开源文档 <a class="header-anchor" href="#整理混乱的开源文档" aria-label="Permalink to “整理混乱的开源文档”">​</a></h3><p>遵循一个“文档风格指南”是很重要的。风格指南是创建和展示内容的指导方针的集合。无论你是一个独立的作家还是一个大型文档团队的成员，它都有助于在你的文档中保持一致的风格、口音和语气。</p><p>有几个流行的风格指南，如《红帽风格指南》、《谷歌文档风格指南》和《苹果风格指南》。如何选用？首先要从定义你的需求开始。如果你的要求与其他开源项目没有太大区别，你可以遵循一个现成的风格指南，或者你也可以先选一个，然后在它的基础上根据自身需要做一些修改。大多数与语法有关的准则和内容规则可能是通用的，但整体术语可能会有所不同。</p><p>你还需要在你的项目中自动采用这些风格指南。为此，你可以使用 Vale，它集成了本地的持续集成（CI）服务，该服务能帮助你确保文档严格遵循风格指南。</p><blockquote><p><strong>文档类型</strong></p><ul><li><em>自述文件</em>：包含基本的安装和使用说明，这也是任何开源文档中最重要的部分之一。它是潜在的用户/开发者与项目之间的第一个连接点。</li><li><em>参考指南</em>：可能包括一些基本的参考资料，以便帮助你快速上手，或者是与项目贡献相关的文档。</li><li><em>用户文档</em>：是最基本的文档，它描述了项目的使用方式。如果没有用户文档，大多数人就会对如何使用该项目感到迷茫。</li><li><em>开发文档</em>：旨在支持开发团队在项目中不断取得新的进展。它还应该为内部开发工作提供一个良好的途径，并确保功能被很好地传达给股东。</li><li><em>社区内容</em>：包括基本的博客、视频和外部内容，旨在为那些想进一步了解项目的社区成员提供支持。</li></ul></blockquote><p>通过使用风格指南，文件的整体前提将以统一的语言风格传达给用户。但是，这些文件毕竟是由一个技术作家团队准备的，它们的写作风格可能会冲突，因为写作风格是因人而异的。那么，如何才能使文档规范化呢？</p><h3 id="规范化文档" tabindex="-1">规范化文档 <a class="header-anchor" href="#规范化文档" aria-label="Permalink to “规范化文档”">​</a></h3><p>当涉及到规范化文档时，有许多方法可以采取。第一个方法显然是创建适用于各种角色的预定义模板。这些模板可以用来记录新的功能、识别错误和问题，以及更新变更日志以适应正在增加的新内容。</p><p>如果你采用的是基于 Git 的工作流，试着开发一个规范的工作流程来发布你的文档。最规范的工作流是：<ruby>复刻<rt>fork</rt></ruby> 发布文档的仓库，在本地分支上添加你的修改，推送这些修改，提出请求并要求对其进行审查。规范化文档的一个好处就是带来更好的反馈和审查过程。</p><h3 id="反馈和自动审查" tabindex="-1">反馈和自动审查 <a class="header-anchor" href="#反馈和自动审查" aria-label="Permalink to “反馈和自动审查”">​</a></h3><p>规范化使得你能够得到用户的反馈并生成自动的审查，可以参考这些反馈来改进项目和文档。通过这些反馈，你也可以评估所分享的信息对用户是否有意义。像 GitBook 这样的文档平台会提供合适的反馈服务，这有助于验证文档是否有用。</p><p>始终寻求<ruby>主题专家<rt>subject matter expert</rt></ruby>（SME）对文档的反馈，他们可以是利益相关者、开发者、工程师，甚至是外部贡献者。你也可以使用自动测试和 CI 来验证你的文档是否遵循风格指南。</p><h3 id="文档众包" tabindex="-1">文档众包 <a class="header-anchor" href="#文档众包" aria-label="Permalink to “文档众包”">​</a></h3><p>如果你想开源你的文档，最好的方法也许是提供一个快速入门指南。它可以像 <code>CONTRIBUTING.md</code> 那样简单，基本上只要说明该如何设置项目并为其作出贡献/单纯使用它即可。</p><p>始终开发以用户为中心的文档，标明每个项目的目的。同时，打造学习课程来帮助新的贡献者。</p><blockquote><p><strong>带着目的编写文档</strong></p><p>始终带着目的编写文档。它是最基本的写作策略之一，它定义了你编写某个特定文档的理由，而非方式。首先回答以下问题：</p><ul><li>这个文档的目标是什么？</li><li>需要传递的信息是什么？</li><li>你希望用户在这之后采取什么行动？</li><li>我与读者分享的价值观是什么？</li><li>我的文档风格是否简洁、一致？</li></ul></blockquote><h3 id="定义一致的内容策略" tabindex="-1">定义一致的内容策略 <a class="header-anchor" href="#定义一致的内容策略" aria-label="Permalink to “定义一致的内容策略”">​</a></h3><p>一致的内容策略有助于确保文档工作和项目基础设施的长期愿景。它可以围绕以下两个主要方面：</p><ol><li>资源：包括项目文档、案例研究和白皮书、项目架构等</li><li>品牌内容：博客和特邀帖子、新闻和社区故事、学习课程等</li></ol><p>每个开源项目都应该有适当的文档，以说明它能为用户提供的功能，这样用户就可以选择最合适的解决方案。适当的文档可以传达正确的信息，也可以让其他开发者贡献力量来进一步加强和改进项目。虽然听起来很简单，但只有做对了，文档才能成功。而你的项目，反过来，只有在你的文档正确的情况下才能成功，所以永远不要低估它的目标或过程！</p><p>策划：Laveesh Kocher</p><hr>',34)),l("p",null,[t[1]||(t[1]=e("via: ",-1)),a(r,{href:"https://www.opensourceforu.com/2022/04/documentation-isnt-just-another-aspect-of-open-source-development/"},{default:o(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/04/documentation-isnt-just-another-aspect-of-open-source-development/",-1)])]),_:1})]),l("p",null,[t[6]||(t[6]=e("作者：",-1)),a(r,{href:"https://www.opensourceforu.com/author/harsh-bardhan-mishra/"},{default:o(()=>[...t[2]||(t[2]=[e("Harsh Bardhan Mishra",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),a(r,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),a(r,{href:"https://github.com/lkxed"},{default:o(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const g=n(d,[["render",m]]);export{C as __pageData,g as default};
